-- Migration V11: Initial Catalog Data
-- Inserts canonical categories, brands, products, variants, volume tiers, initial stock movements, and product images.

-- 1. Categories
ON CONFLICT (slug) DO NOTHING;

-- 2. Brands
ON CONFLICT (slug) DO NOTHING;

-- 3. Products
ON CONFLICT (slug) DO NOTHING;

-- 4. Variants
ON CONFLICT (sku) DO NOTHING;

-- 5. Wholesale Volume Tiers
ON CONFLICT (variant_id, min_qty) DO NOTHING;

-- 6. Initial Stock Movements for Variant Stock Reconciliation
SELECT v.id, v.stock_on_hand, 'INITIAL', 'Initial catalog migration V11'
FROM variant v
WHERE v.sku IN ('PKL-001', 'PKL-002', 'PKL-003', 'PKL-004', 'PKL-005', 'PKL-006', 'PKL-007', 'PKL-008', 'PKL-009', 'PKL-010', 'PKL-011', 'PKL-012', 'TRS-001', 'TRS-002', 'TRS-003', 'TRS-004', 'TRS-005', 'TRS-006', 'TRS-007', 'TRS-008', 'TRS-009', 'TRS-010', 'TRS-011', 'TRS-012', 'OLV-001', 'OLV-002', 'OLV-003', 'OLV-004', 'OLV-005', 'PST-001', 'CHS-001', 'CHS-002', 'CHS-003', 'CHS-004', 'CHS-005', 'CRN-001', 'POT-001', 'POT-002', 'SCE-001', 'SCE-002', 'SCE-003', 'SCE-004', 'SCE-005', 'SCE-006', 'DELI-001', 'DELI-002', 'DELI-003', 'DELI-004', 'DELI-005', 'DELI-006', 'DELI-007', 'DELI-008', 'DELI-009', 'DELI-010', 'DELI-011', 'DELI-012', 'DELI-013', 'DELI-014', 'DELI-015', 'DELI-016', 'DELI-017', 'DELI-018', 'DELI-019', 'DELI-020', 'DELI-021', 'DELI-022', 'DELI-023', 'DELI-024', 'DELI-025', 'DELI-026', 'DELI-027', 'DELI-028', 'DELI-029', 'DELI-030')
  AND v.stock_on_hand > 0
  AND NOT EXISTS (
      SELECT 1 FROM stock_movement sm WHERE sm.variant_id = v.id AND sm.reason = 'INITIAL'
  );

-- 7. Product Images
SELECT p.id, 'products/' || p.slug || '/main', 1, p.name_fa, p.name_en
FROM product p
WHERE p.slug IN ('pws-pkl-001', 'pws-pkl-002', 'pws-pkl-003', 'pws-pkl-004', 'pws-pkl-005', 'pws-pkl-006', 'pws-pkl-007', 'pws-pkl-008', 'pws-pkl-009', 'pws-pkl-010', 'pws-pkl-011', 'pws-pkl-012', 'pws-trs-001', 'pws-trs-002', 'pws-trs-003', 'pws-trs-004', 'pws-trs-005', 'pws-trs-006', 'pws-trs-007', 'pws-trs-008', 'pws-trs-009', 'pws-trs-010', 'pws-trs-011', 'pws-trs-012', 'pws-olv-001', 'pws-olv-002', 'pws-olv-003', 'pws-olv-004', 'pws-olv-005', 'pws-pst-001', 'pws-chs-001', 'pws-chs-002', 'pws-chs-003', 'pws-chs-004', 'pws-chs-005', 'pws-crn-001', 'pws-pot-001', 'pws-pot-002', 'pws-sce-001', 'pws-sce-002', 'pws-sce-003', 'pws-sce-004', 'pws-sce-005', 'pws-sce-006', 'pws-deli-001', 'pws-deli-002', 'pws-deli-003', 'pws-deli-004', 'pws-deli-006', 'pws-deli-007', 'pws-deli-011', 'pws-deli-012', 'pws-deli-016', 'pws-deli-017', 'pws-deli-019', 'pws-deli-020', 'pws-deli-022', 'pws-deli-026')
  AND NOT EXISTS (
      SELECT 1 FROM product_image pi WHERE pi.product_id = p.id AND pi.path = 'products/' || p.slug || '/main'
  );
